const contratos = $input.all().map(item => item.json);
const inputData = $('trigger_herramienta').first().json;
const query = inputData.query?.toLowerCase()?.trim() || '';
const diaInicio = inputData.dia_inicio || inputData.dia || '';
const diaFin = inputData.dia_fin || '';
const verVencimientos = inputData.ver_vencimientos || '';
const verBancarios = inputData.ver_bancarios || '';

// Fecha de hoy sin hora
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const diaHoy = hoy.getDate();
const mesHoy = hoy.getMonth();
const anioHoy = hoy.getFullYear();

// Fecha de mañana
const manana = new Date(hoy);
manana.setDate(manana.getDate() + 1);
const diaManana = manana.getDate();

// Quitar tildes para búsqueda
function sinTildes(str) {
  return String(str || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

// Limpiar número (quitar comas)
function limpiarNumero(valor) {
  if (!valor) return 0;
  const limpio = String(valor).replace(/,/g, '').replace(/[^0-9.-]/g, '');
  return parseFloat(limpio) || 0;
}

// Calcular fecha final del contrato
function calcularFechaFinal(inicio, meses) {
  if (!inicio || !meses) return null;
  const fecha = new Date(inicio);
  fecha.setMonth(fecha.getMonth() + parseInt(meses));
  fecha.setHours(0, 0, 0, 0);
  return fecha;
}

// Formatear fecha legible
function formatearFecha(fecha) {
  if (!fecha) return 'N/A';
  return fecha.toISOString().split('T')[0];
}

// ⭐ LÓGICA ACTUALIZADA: Verificar si contrato está activo
function estaActivo(c) {
  // REGLA #1: Si Estatus Operativo contiene CANCELADO → INACTIVO
  const estatusOperativo = String(c['Estatus Operativo'] || '').toUpperCase();
  if (estatusOperativo.includes('CANCELADO')) return false;

  // REGLA #2: Revisar Estatus Contrato
  const estatusContrato = String(c['Estatus Contrato'] || '').toUpperCase();

  // Si es VENCIDO o POR ACTIVAR → INACTIVO
  if (estatusContrato === 'VENCIDO' || estatusContrato === 'POR ACTIVAR') return false;

  // Si es ACTIVO o POR VENCER → ACTIVO
  if (estatusContrato === 'ACTIVO' || estatusContrato === 'POR VENCER') return true;

  // Si no tiene estatus definido, usar fecha como fallback
  const fechaFinal = calcularFechaFinal(c.Inicio, c.Meses);
  if (!fechaFinal) return false;
  return hoy <= fechaFinal;
}

// Procesar todos los contratos
let todosContratos = contratos.map(c => {
  const fechaFinal = calcularFechaFinal(c.Inicio, c.Meses);
  return {
    ...c,
    FechaFinal: fechaFinal,
    FechaFinalStr: formatearFecha(fechaFinal),
    ContratoActivo: estaActivo(c),
    MensualNum: limpiarNumero(c.Mensual),
    CapitalNum: limpiarNumero(c.Capital)
  };
});

let respuesta = '';
let crearSheet = false;
let datosParaSheet = [];
let tituloSheet = '';

// ========== CONSULTA DE VENCIMIENTOS ==========
if (verVencimientos === 'este_mes') {
  const vencenEsteMes = todosContratos.filter(c => {
    if (!c.FechaFinal || !c.ContratoActivo) return false;
    return c.FechaFinal.getMonth() === mesHoy && c.FechaFinal.getFullYear() === anioHoy;
  });

  const porUSD = vencenEsteMes.filter(c => c.Moneda === 'USD');
  const porCAD = vencenEsteMes.filter(c => c.Moneda === 'CAD');

  // Si son más de 15, crear Sheet
  if (vencenEsteMes.length > 15) {
    crearSheet = true;
    tituloSheet = `Vencimientos_${anioHoy}-${String(mesHoy+1).padStart(2,'0')}`;
    datosParaSheet = vencenEsteMes.map(c => ({
      Nombre: c.Nombre,
      Capital: c.Capital,
      Moneda: c.Moneda,
      Mensual: c.Mensual,
      Dia_Pago: c.Dia,
      Fecha_Vencimiento: c.FechaFinalStr,
      Estatus: c['Estatus Contrato']
    }));
    respuesta = `📅 VENCIMIENTOS ESTE MES: ${vencenEsteMes.length} contratos\n\n💵 USD: ${porUSD.length}\n🍁 CAD: ${porCAD.length}\n\n⏳ Generando reporte en Google Sheets...`;
  } else {
    respuesta = `📅 CONTRATOS QUE VENCEN ESTE MES:\n\nTotal: ${vencenEsteMes.length} contratos\n\n`;
    if (porUSD.length > 0) {
      respuesta += `💵 USD (${porUSD.length}):\n`;
      porUSD.forEach(c => { respuesta += `• ${c.Nombre}: $${c.Capital}, vence ${c.FechaFinalStr}\n`; });
      respuesta += `\n`;
    }
    if (porCAD.length > 0) {
      respuesta += `🍁 CAD (${porCAD.length}):\n`;
      porCAD.forEach(c => { respuesta += `• ${c.Nombre}: $${c.Capital}, vence ${c.FechaFinalStr}\n`; });
    }
    if (vencenEsteMes.length === 0) respuesta = `No hay contratos que venzan este mes.`;
  }

  return [{ json: { respuesta, crearSheet, datosParaSheet, tituloSheet } }];
}

// ========== FILTRAR CONTRATOS ACTIVOS ==========
let resultado = todosContratos.filter(c => c.ContratoActivo);

// Filtrar por nombre si hay query
if (query) {
  const queryNorm = sinTildes(query).toLowerCase();
  resultado = resultado.filter(c => sinTildes(c.Nombre).toLowerCase().includes(queryNorm));
}

// Filtrar por día o rango de días
if (diaInicio) {
  const diaIni = parseInt(diaInicio);
  const diaF = diaFin ? parseInt(diaFin) : diaIni;
  resultado = resultado.filter(c => {
    const dia = parseInt(c.Dia);
    return dia >= diaIni && dia <= diaF;
  });
}

// Agrupar por divisa
const porUSD = resultado.filter(c => c.Moneda === 'USD');
const porCAD = resultado.filter(c => c.Moneda === 'CAD');
const totalUSD = porUSD.reduce((sum, c) => sum + c.MensualNum, 0);
const totalCAD = porCAD.reduce((sum, c) => sum + c.MensualNum, 0);
const nombresUnicos = [...new Set(resultado.map(c => c.Nombre))];

// ========== CONSULTA DE DATOS BANCARIOS ==========
if (verBancarios === 'si' && query) {
  respuesta = `🏦 DATOS BANCARIOS:\n\n`;
  if (resultado.length === 0) {
    respuesta = `No encontré cliente con nombre "${query}".`;
  } else if (nombresUnicos.length > 1) {
    respuesta = `Encontré ${nombresUnicos.length} clientes con "${query}":\n`;
    nombresUnicos.forEach((nombre, i) => { respuesta += `${i + 1}. ${nombre}\n`; });
    respuesta += `\n¿De cuál quieres los datos bancarios?`;
  } else {
    nombresUnicos.forEach(nombre => {
      const contrato = resultado.find(c => c.Nombre === nombre);
      respuesta += `👤 ${nombre}\n💰 Divisa: ${contrato.Moneda}\n`;
      const cuenta = String(contrato.Cuenta || '').trim();
      respuesta += cuenta !== '' ? `💳 Datos:\n${cuenta}\n` : `⚠️ Sin datos bancarios registrados\n`;
    });
  }
  return [{ json: { respuesta, crearSheet: false, datosParaSheet: [], tituloSheet: '' } }];
}

// ========== CASO: No hay resultados ==========
if (resultado.length === 0 && (query || diaInicio)) {
  respuesta = `No encontré contratos activos${query ? ` para "${query}"` : ''}${diaInicio ? ` con día de pago ${diaInicio}${diaFin ? ` al ${diaFin}` : ''}` : ''}.`;
  return [{ json: { respuesta, crearSheet: false, datosParaSheet: [], tituloSheet: '' } }];
}

// ========== CASO: Múltiples clientes con mismo nombre ==========
if (nombresUnicos.length > 1 && query) {
  respuesta = `Encontré ${nombresUnicos.length} clientes con "${query}":\n`;
  nombresUnicos.forEach((nombre, i) => {
    const contratosCliente = resultado.filter(c => c.Nombre === nombre);
    respuesta += `${i + 1}. ${nombre} (${contratosCliente.length} contrato${contratosCliente.length > 1 ? 's' : ''})\n`;
  });
  respuesta += `\n¿Cuál te interesa?`;
  return [{ json: { respuesta, crearSheet: false, datosParaSheet: [], tituloSheet: '' } }];
}

// ========== CASO: Mostrar detalle (query o día específico) ==========
if (query || diaInicio) {
  // Determinar título
  if (diaInicio && diaFin && diaInicio !== diaFin) {
    tituloSheet = `Pagos_Dia_${diaInicio}_al_${diaFin}`;
    respuesta = `📅 PAGOS DEL DÍA ${diaInicio} AL ${diaFin}:\n\n`;
  } else if (diaInicio) {
    tituloSheet = `Pagos_Dia_${diaInicio}`;
    respuesta = `📅 PAGOS DEL DÍA ${diaInicio}:\n\n`;
  } else if (query && nombresUnicos.length === 1) {
    tituloSheet = `Contratos_${nombresUnicos[0].replace(/\s+/g, '_')}`;
    respuesta = `📋 CONTRATOS DE ${nombresUnicos[0].toUpperCase()}:\n\n`;
  } else {
    tituloSheet = `Consulta_${Date.now()}`;
    respuesta = `Encontré ${resultado.length} contrato${resultado.length > 1 ? 's' : ''}:\n\n`;
  }

  // Si son más de 15, crear Sheet
  if (resultado.length > 15) {
    crearSheet = true;
    datosParaSheet = resultado.map(c => ({
      Nombre: c.Nombre,
      Capital: c.Capital,
      Moneda: c.Moneda,
      Mensual: c.Mensual,
      Dia_Pago: c.Dia,
      Fecha_Vencimiento: c.FechaFinalStr,
      Estatus: c['Estatus Contrato']
    }));
    respuesta += `💵 USD: ${porUSD.length} contratos — Total: $${totalUSD.toFixed(2)}/mes\n`;
    respuesta += `🍁 CAD: ${porCAD.length} contratos — Total: $${totalCAD.toFixed(2)}/mes\n\n`;
    respuesta += `📊 Son ${resultado.length} contratos. Generando reporte en Google Sheets...`;
  } else {
    if (porUSD.length > 0) {
      respuesta += `💵 USD (${porUSD.length}):\n`;
      porUSD.forEach(c => { respuesta += `• ${c.Nombre}: Capital $${c.Capital}, Rinde $${c.Mensual}/mes, Día ${c.Dia}, Vence ${c.FechaFinalStr}\n`; });
      respuesta += `TOTAL USD: $${totalUSD.toFixed(2)}/mes\n\n`;
    }
    if (porCAD.length > 0) {
      respuesta += `🍁 CAD (${porCAD.length}):\n`;
      porCAD.forEach(c => { respuesta += `• ${c.Nombre}: Capital $${c.Capital}, Rinde $${c.Mensual}/mes, Día ${c.Dia}, Vence ${c.FechaFinalStr}\n`; });
      respuesta += `TOTAL CAD: $${totalCAD.toFixed(2)}/mes\n`;
    }
  }

  return [{ json: { respuesta, crearSheet, datosParaSheet, tituloSheet } }];
}

// ========== CASO: RESUMEN GENERAL ==========
const totalActivos = todosContratos.filter(c => c.ContratoActivo).length;
const totalInactivos = todosContratos.filter(c => !c.ContratoActivo).length;
const activosUSD = todosContratos.filter(c => c.ContratoActivo && c.Moneda === 'USD');
const activosCAD = todosContratos.filter(c => c.ContratoActivo && c.Moneda === 'CAD');
const totalGeneralUSD = activosUSD.reduce((sum, c) => sum + c.MensualNum, 0);
const totalGeneralCAD = activosCAD.reduce((sum, c) => sum + c.MensualNum, 0);

// Pagos de hoy
const pagosHoy = todosContratos.filter(c => c.ContratoActivo && parseInt(c.Dia) === diaHoy);
const pagosHoyUSD = pagosHoy.filter(c => c.Moneda === 'USD');
const pagosHoyCAD = pagosHoy.filter(c => c.Moneda === 'CAD');
const totalHoyUSD = pagosHoyUSD.reduce((sum, c) => sum + c.MensualNum, 0);
const totalHoyCAD = pagosHoyCAD.reduce((sum, c) => sum + c.MensualNum, 0);

// Pagos de mañana
const pagosManana = todosContratos.filter(c => c.ContratoActivo && parseInt(c.Dia) === diaManana);
const pagosManaUSD = pagosManana.filter(c => c.Moneda === 'USD');
const pagosManaCAD = pagosManana.filter(c => c.Moneda === 'CAD');
const totalManaUSD = pagosManaUSD.reduce((sum, c) => sum + c.MensualNum, 0);
const totalManaCAD = pagosManaCAD.reduce((sum, c) => sum + c.MensualNum, 0);

respuesta = `📊 RESUMEN GENERAL:\n\n`;
respuesta += `✅ Contratos activos: ${totalActivos}\n`;
respuesta += `   💵 USD: ${activosUSD.length} contratos\n`;
respuesta += `   🍁 CAD: ${activosCAD.length} contratos\n`;
respuesta += `❌ Contratos inactivos: ${totalInactivos}\n\n`;
respuesta += `💰 RENDIMIENTOS MENSUALES:\n`;
respuesta += `   💵 USD: $${totalGeneralUSD.toFixed(2)}/mes\n`;
respuesta += `   🍁 CAD: $${totalGeneralCAD.toFixed(2)}/mes\n\n`;
respuesta += `📅 PAGOS HOY (Día ${diaHoy}):\n`;
if (pagosHoy.length > 0) {
  respuesta += `   ${pagosHoy.length} contratos\n`;
  if (pagosHoyUSD.length > 0) respuesta += `   💵 USD: $${totalHoyUSD.toFixed(2)} (${pagosHoyUSD.length})\n`;
  if (pagosHoyCAD.length > 0) respuesta += `   🍁 CAD: $${totalHoyCAD.toFixed(2)} (${pagosHoyCAD.length})\n`;
} else {
  respuesta += `   No hay pagos hoy\n`;
}
respuesta += `\n📆 PAGOS MAÑANA (Día ${diaManana}):\n`;
if (pagosManana.length > 0) {
  respuesta += `   ${pagosManana.length} contratos\n`;
  if (pagosManaUSD.length > 0) respuesta += `   💵 USD: $${totalManaUSD.toFixed(2)} (${pagosManaUSD.length})\n`;
  if (pagosManaCAD.length > 0) respuesta += `   🍁 CAD: $${totalManaCAD.toFixed(2)} (${pagosManaCAD.length})\n`;
} else {
  respuesta += `   No hay pagos mañana\n`;
}

return [{ json: { respuesta, crearSheet: false, datosParaSheet: [], tituloSheet: '' } }];

const datosParaSheet = $('formatear_respuesta').first().json.datosParaSheet;

return datosParaSheet.map(item => ({
  json: item
}));
